import shelve
import os
from cryptography.fernet import Fernet


def persist_session(
    session_id: str,
    access_token: str,
    refresh_token: str,
) -> None:
    # Retrieve the encryption key from environment variables.
    # This key must be a URL-safe base64-encoded 32-byte key, typically generated by Fernet.generate_key().
    encryption_key_str = os.environ.get("SESSION_ENCRYPTION_KEY")

    if not encryption_key_str:
        # It is critical to have an encryption key for sensitive data.
        # If the key is not set, the application cannot securely store data.
        raise ValueError("SESSION_ENCRYPTION_KEY environment variable not set.")

    try:
        # Initialize Fernet with the provided key. The key must be bytes.
        f = Fernet(encryption_key_str.encode('utf-8'))
    except Exception as e:
        # Catch potential issues with the key format (e.g., not valid base64, incorrect length).
        raise ValueError(f"Invalid SESSION_ENCRYPTION_KEY format: {e}")

    # Encrypt the sensitive tokens before storing them.
    # Fernet operates on bytes, so encode strings to bytes first.
    encrypted_access_token = f.encrypt(access_token.encode('utf-8'))
    encrypted_refresh_token = f.encrypt(refresh_token.encode('utf-8'))

    with shelve.open(
        "sessions.db",
    ) as store:
        store[session_id] = {
            "access_token": encrypted_access_token,
            "refresh_token": encrypted_refresh_token,
        }
